-- 2. Tags: contract metadata on the table, classification on the columns
ALTER STREAMING TABLE silver.orders SET TAGS ('contract_id' = 'urn:datacontract:sales:orders', 'contract_version' = '1.0.0', 'contract_status' = 'active', 'data_domain' = 'sales', 'data_product' = 'orders', 'layer' = 'silver', 'owner_team' = 'Order Management', 'support_channel' = 'orders-data-support', 'sla_freshness' = '24h', 'sla_retention' = '7y');
ALTER STREAMING TABLE silver.orders ALTER COLUMN customer_email SET TAGS ('pii' = 'email', 'classification' = 'confidential');
ALTER STREAMING TABLE bronze.orders_raw SET TAGS ('contract_id' = 'urn:datacontract:sales:orders', 'layer' = 'bronze', 'owner_team' = 'Order Management');
ALTER STREAMING TABLE silver.orders_quarantine SET TAGS ('contract_id' = 'urn:datacontract:sales:orders', 'layer' = 'quarantine', 'owner_team' = 'Order Management');
-- Contract status drives the certified / deprecated badge in Catalog Explorer
SET TAG ON TABLE silver.orders `system.certification_status` = `certified`;

