GRANT SELECT ON TABLE silver.orders TO `sales_analysts`;
GRANT SELECT ON TABLE silver.orders TO `orders_producers`;
GRANT SELECT ON TABLE silver.orders_quarantine TO `orders_producers`;
GRANT SELECT ON TABLE bronze.orders_raw TO `orders_producers`;
